package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
import java.util.*;
/** Actual Source loaded topology, ordering, partition and bounded overflow outcomes. */
public final class ScreenRectangleChecks {
 private record Node(int index,int x,int y,int z,int meta){}
 public static void main(String[] args)throws Exception{JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenRectanglesReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0,queries=0;for(var entry:reference.getAsJsonArray("cases")){var source=entry.getAsJsonObject();var family=ScreenFamily.fromId(source.get("id").getAsString());var nodes=new ArrayList<Node>();var map=new HashMap<String,Node>();for(var value:source.getAsJsonArray("nodes")){var n=value.getAsJsonArray();var node=new Node(nodes.size(),n.get(0).getAsInt(),n.get(1).getAsInt(),n.get(2).getAsInt(),n.get(3).getAsInt());nodes.add(node);map.put(key(node.x,node.y,node.z),node);}boolean boundary=source.get("boundary").getAsBoolean();var access=new ScreenRectangleGroups.Access<Node>(){public int x(Node n){return n.x;}public int y(Node n){return n.y;}public int z(Node n){return n.z;}public boolean loaded(int x,int y,int z){return !boundary||(x>>4)==0&&(z>>4)==0;}public Node at(int x,int y,int z){if(!loaded(x,y,z))throw new AssertionError("unloaded access");return map.get(key(x,y,z));}public boolean compatible(Node a,Node b){return a.meta==b.meta;}};int q=0;for(var query:source.getAsJsonArray("queries")){var origin=nodes.get(query.getAsInt());var basis=ScreenJoinGeometry.basis(family,family.decode(origin.meta),false);var result=ScreenRectangleGroups.discover(origin,basis,access,ScreenJoinGeometry.supports(family,false));var actual=new JsonArray();for(var member:result.members(origin))actual.add(member.index);if(!actual.equals(source.getAsJsonArray("edit").get(q))||!actual.equals(source.getAsJsonArray("power").get(q)))throw new AssertionError("Source rectangles differ case="+cases+" query="+q+" actual="+actual+" edit="+source.getAsJsonArray("edit").get(q)+" power="+source.getAsJsonArray("power").get(q));q++;queries++;}cases++;}if(cases!=1124||!reference.get("sha256").getAsString().equals("11ac292041c061ede9cabd982e1b6eb273e88c6ec77a7d129977a12af3c045d6"))throw new AssertionError("Source rectangle coverage");System.out.println("Native Screen rectangles PASS actual Source cases="+cases+" queries="+queries+" holes/state barriers/loaded edges/1024 bound");}
 private static String key(int x,int y,int z){return x+","+y+","+z;}
}
